import {HUB as r} from './registration.mjs';
export const dataRecord=(o,keys)=>{if(!o||Object.getPrototypeOf(o)!==Object.prototype||Reflect.ownKeys(o).length!==keys.length)return null;const v={};for(const k of keys){const d=Object.getOwnPropertyDescriptor(o,k);if(!d?.enumerable||!Object.hasOwn(d,'value'))return null;v[k]=d.value}return v};
export const footPair=f=>Array.isArray(f)&&Object.getPrototypeOf(f)===Array.prototype&&Reflect.ownKeys(f).length===3&&f.length===2&&['0','1'].every(k=>{const d=Object.getOwnPropertyDescriptor(f,k);return d?.enumerable&&Object.hasOwn(d,'value')&&Number.isSafeInteger(d.value)});
export function inHubContact(point,foot,facing){if(!footPair(foot))return false;return(point.readZones??[point]).some(p=>p.facing===facing&&p.approachRows.some(([y,a,z])=>foot[1]===y&&foot[0]>=a&&foot[0]<z))}
export const digest=async b=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',b)),x=>x.toString(16).padStart(2,'0')).join('');
export async function pinnedBytes(pin,{signal,fetcher=fetch}={}){if(signal?.aborted)throw Error('HUB_ABORTED');const res=await fetcher(new URL(pin.file,import.meta.url),{signal});if(!res.ok)throw Error('HUB_RESOURCE_HTTP');const b=(await res.arrayBuffer()).slice(0);if(await digest(b)!==pin.sha256)throw Error('HUB_PIN_MISMATCH');if(signal?.aborted)throw Error('HUB_ABORTED');return b}
function decodeRows(b){const rows=JSON.parse(new TextDecoder().decode(b)),mask=new Uint8Array(r.size[0]*r.size[1]);if(!Array.isArray(rows))throw Error('HUB_MASK');let last=-1;for(const row of rows){if(!Array.isArray(row)||row.length!==3||!row.every(Number.isSafeInteger))throw Error('HUB_MASK');const[y,a,z]=row,lo=y*r.size[0]+a,hi=y*r.size[0]+z;if(y<0||y>=r.size[1]||a<0||z>r.size[0]||a>=z||lo<=last)throw Error('HUB_MASK');mask.fill(1,lo,hi);last=hi-1}return mask}
export async function prepareHubSupport({signal,fetcher=fetch}={}){let disposed=false,mask=null;const zones=new Map;const dispose=()=>{if(disposed)return;disposed=true;mask=null;zones.clear();signal?.removeEventListener('abort',dispose)};try{mask=decodeRows(await pinnedBytes(r.support,{signal,fetcher}));for(const[k,p]of Object.entries(r.wildZones))zones.set(k,decodeRows(await pinnedBytes(p,{signal,fetcher})));if(signal?.aborted)throw Error('HUB_ABORTED');signal?.addEventListener('abort',dispose,{once:true})}catch(e){dispose();throw e}
const safe=f=>!disposed&&footPair(f)&&f[0]>=0&&f[1]>=0&&f[0]<r.size[0]&&f[1]<r.size[1]&&mask[f[1]*r.size[0]+f[0]]===1;
const describe=(foot,facing)=>{if(!safe(foot)||!['up','down','left','right'].includes(facing))throw Error('HUB_POSE_SUPPORT');return{version:1,sceneId:r.sceneId,mapId:r.mapId,revision:r.revision,imageSHA:r.image.sha256,maskSHA:r.support.sha256,foot:[...foot],facing,state:0}};
const validate=p=>{try{const v=dataRecord(p,['version','sceneId','mapId','revision','imageSHA','maskSHA','foot','facing','state']);if(!v)return false;const expected=describe(v.foot,v.facing);return ['version','sceneId','mapId','revision','imageSHA','maskSHA','facing','state'].every(k=>v[k]===expected[k])&&v.foot[0]===expected.foot[0]&&v.foot[1]===expected.foot[1]}catch{return false}};
const contact=(id,foot,facing)=>{if(!safe(foot))return false;const p=r.points.find(p=>p.pointId===id);return !!p&&inHubContact(p,foot,facing)};
const resolveContact=(foot,facing)=>{if(!safe(foot))return null;const hits=r.points.filter(p=>inHubContact(p,foot,facing));return hits.length===1?hits[0].pointId:null};
const wildZone=foot=>{if(!safe(foot))return null;const i=foot[1]*r.size[0]+foot[0];for(const[k,m]of zones)if(m[i])return{zone:k,tableId:r.wildTableId};return null};
return Object.freeze({registration:r,get pinsVerified(){return !disposed},safe,describe,validate,contact,resolveContact,wildZone,dispose});}
